package com.kge.energy.crm.qrcode;

import cn.hutool.core.codec.Base64;
import cn.hutool.core.io.FileUtil;
import cn.hutool.extra.qrcode.QrConfig;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.awt.*;
import java.io.File;

@Configuration
public class QRConfig {

    public static final String LOGO_BASE64 ="";

    public static final String LOGO_PATH = "/tmp/logo.png";


    /**
     * 采用JavaConfig的方式显示注入hutool中 生成二维码
     *
     * @return
     */
    @Bean
    public QrConfig qrConfig() {
        //初始宽度和高度
        QrConfig qrConfig = new QrConfig(300, 300);
        //设置边距，即二维码和边框的距离
        qrConfig.setMargin(2);
        //设置前景色
        qrConfig.setForeColor(Color.BLACK.getRGB());
        //设置背景色
        qrConfig.setBackColor(Color.WHITE.getRGB());
        //设置二维码中间的logo
        File file = new File(LOGO_PATH);
        if (!file.exists()) {
            byte[] image = Base64.decode(LOGO_BASE64);
            file = FileUtil.writeBytes(image, LOGO_PATH);
        }
        qrConfig.setImg(file);
        //设置二维码中间Logo缩放的比例系数，4表示长宽最小值的1/4
        qrConfig.setRatio(4);
        return qrConfig;
    }

}